const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) {
  throw new Error('Odoo config not found. Run odoo_setup_crm.py --apply and check ODOO_* env vars. ' +
    JSON.stringify(cfgRes.error || '').slice(0, 300));
}
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };
const errText = (e) => (e && (e.data?.message || e.message)) || JSON.stringify(e || '').slice(0, 200);

return [{ json: { rpc: { model: 'crm.lead', method: 'search_read',
  args: [[['company_id', '=', cfg.company_id], ['stage_id', '=', cfg.stage_ids.Qualified], ['x_clickup_task_id', '=', false]]],
  kwargs: { fields: ["id", "name", "contact_name", "email_from", "phone", "city", "description", "x_lead_ref", "x_clickup_task_id"], limit: 20, context } } } }];

// One ClickUp task per Qualified lead that has no task yet. Due in 3 days.
const r = $input.first().json;
if (r.error) throw new Error('Odoo: ' + (r.error.data?.message || r.error.message));
const plain = (h) => String(h || '').replace(/<\/li>/g, '\n').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").trim();
const due = new Date(Date.now() + 3 * 86400000).toISOString();
return (r.result || []).map(l => ({ json: { lead: l, due,
  task_name: `Site survey – ${l.contact_name || l.name} – ${l.city || 'city not set'}`,
  task_content: [`Odoo lead #${l.id}: ${l.name}`, `Customer: ${l.contact_name || '-'}`, `Phone: ${l.phone || '-'}`,
    `Email: ${l.email_from || '-'}`, `City: ${l.city || '-'}`, `Sheet Lead ID: ${l.x_lead_ref || '-'}`, '',
    plain(l.description), '', 'Demo data only (SunGuard Solar & CCTV is fictional).'].join('\n') } }));

const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) {
  throw new Error('Odoo config not found. Run odoo_setup_crm.py --apply and check ODOO_* env vars. ' +
    JSON.stringify(cfgRes.error || '').slice(0, 300));
}
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };
const errText = (e) => (e && (e.data?.message || e.message)) || JSON.stringify(e || '').slice(0, 200);

// Save the ClickUp task ID on the lead so the task is never created twice.
const leads = $('Leads needing a task').all();
return $input.all().map((it, i) => ({ json: { lead: leads[i].json.lead, task_id: String(it.json.id), due: leads[i].json.due,
  rpc: { model: 'crm.lead', method: 'write', args: [[leads[i].json.lead.id], { x_clickup_task_id: String(it.json.id) }],
         kwargs: { context } } } }));

const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) {
  throw new Error('Odoo config not found. Run odoo_setup_crm.py --apply and check ODOO_* env vars. ' +
    JSON.stringify(cfgRes.error || '').slice(0, 300));
}
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };
const errText = (e) => (e && (e.data?.message || e.message)) || JSON.stringify(e || '').slice(0, 200);

const src = $('Save task ID on lead').all();
return $input.all().map((it, i) => {
  const d = src[i].json;
  if (it.json.error) throw new Error('Odoo write failed: ' + errText(it.json.error));
  return { json: { rpc: { model: 'crm.lead', method: 'message_post', args: [[d.lead.id]],
    kwargs: { body: `ClickUp site survey task ${d.task_id} created, due ${d.due.slice(0, 10)}.`,
              message_type: 'comment', subtype_xmlid: 'mail.mt_note', context } } } };
});

