const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) {
  throw new Error('Odoo config not found. Run odoo_setup_crm.py --apply and check ODOO_* env vars. ' +
    JSON.stringify(cfgRes.error || '').slice(0, 300));
}
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };
const errText = (e) => (e && (e.data?.message || e.message)) || JSON.stringify(e || '').slice(0, 200);

// Only tasks marked Complete/Closed in ClickUp move the lead to Proposition.
const src = $('Leads with a task').all();
const out = [];
$input.all().forEach((it, i) => {
  const type = String(it.json.status?.type || '').toLowerCase();
  if (!['done', 'closed'].includes(type)) return;
  const lead = src[i].json.lead;
  out.push({ json: { lead, task_id: src[i].json.task_id,
    rpc: { model: 'crm.lead', method: 'write', args: [[lead.id], { stage_id: cfg.stage_ids.Proposition }], kwargs: { context } } } });
});
return out;

const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) {
  throw new Error('Odoo config not found. Run odoo_setup_crm.py --apply and check ODOO_* env vars. ' +
    JSON.stringify(cfgRes.error || '').slice(0, 300));
}
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };
const errText = (e) => (e && (e.data?.message || e.message)) || JSON.stringify(e || '').slice(0, 200);

const src = $('Only completed tasks').all();
const today = new Date().toISOString().slice(0, 10);
return $input.all().map((it, i) => {
  const d = src[i].json;
  if (it.json.error) throw new Error('Odoo stage change failed: ' + errText(it.json.error));
  return { json: { rpc: { model: 'crm.lead', method: 'message_post', args: [[d.lead.id]],
    kwargs: { body: `Site survey done ${today} (ClickUp task ${d.task_id}). Moved to Proposition.`,
              message_type: 'comment', subtype_xmlid: 'mail.mt_note', context } } } };
});
